  async function carregar() {
    const urls = ['funcionarios','epis','extintores','inspecoes','documentos','exames','empresas','clinicas']
    const res: any = {}
    for (const u of urls) { try { const r = await fetch(`/api/${u}`); const j = await r.json(); res[u] = Array.isArray(j) ? j : j.data || [] } catch { res[u] = [] } }
    try { const localEmp = JSON.parse(localStorage.getItem('previx_empresas')||'[]'); if (localEmp.length) res.empresas = localEmp; if (!localEmp.find((e:any)=>e.login==='solnascente')) { const sol = { id: 'sol1', nome: 'Solnascente LTDA', cnpj: '', responsavel: 'Ronaldo', telefone: '82994145622', email: 'Lojas.cs16486@gmail.com', login: 'solnascente', senha: '12345678', status: 'Ativa' }; if (!res.empresas.find((e:any)=>e.login==='solnascente')) res.empresas.push(sol); localStorage.setItem('previx_empresas', JSON.stringify(res.empresas)) } } catch {}
    try { const localDados = JSON.parse(localStorage.getItem('previx_dados')||'{}'); if (localDados.funcionarios) res.funcionarios = localDados.funcionarios; if (localDados.documentos) res.documentos = localDados.documentos.map((d:any)=>({...d, pasta: d.pasta || d.tipo || 'Outros', tipo: d.pasta || d.tipo || 'Outros'})); if (localDados.empresas) res.empresas = localDados.empresas; if (localDados.epis) res.epis = localDados.epis; if (localDados.exames) res.exames = localDados.exames; if (localDados.clinicas) res.clinicas = localDados.clinicas; if (localDados.inspecoes) res.inspecoes = localDados.inspecoes } catch {}
    if (!res.clinicas || res.clinicas.length===0) { res.clinicas = [{ id:'clin1', nome:'Sol Nascente', cnpj:'', telefone:'(82) 99999-0000', email:'', endereco:'Maceió - AL', responsavel:'', convenio:'Vigente', status:'Ativa', empresa: '' }] }
    if (res.funcionarios) { let mudou=false; res.funcionarios = res.funcionarios.map((f:any)=>{ if (!f.pin) { mudou=true; return {...f, pin: gerarPIN()} } return f }); if (mudou) { try { const ld = JSON.parse(localStorage.getItem('previx_dados')||'{}'); ld.funcionarios = res.funcionarios; localStorage.setItem('previx_dados', JSON.stringify(ld)) } catch {} } }
    if (res.exames) { res.exames = res.exames.map((e:any)=>{ const dataLimpa = limparDataExame(e.data); return { ...e, data: dataLimpa || e.data, nome: e.nome || e.funcionario || e.titulo || 'Registro' } }) }
    setDados(res); if (res.clinicas?.[0]) setClinicaSelecionada(res.clinicas[0].nome)
  }
  function salvarNoNavegador(novosDados:any) { try { localStorage.setItem('previx_empresas', JSON.stringify(novosDados.empresas||[])); localStorage.setItem('previx_dados', JSON.stringify(novosDados)) } catch(e) { alert('⚠️ Arquivo muito grande!') } }
  function limparExamesComErro() { const ruins = (dados.exames||[]).filter((e:any)=> (e.nome==='Registro' || !e.nome || !limparDataExame(e.data))); if (ruins.length===0) { alert('✅ Nenhum exame com erro!'); return }; if (!confirm(`Apagar ${ruins.length} exame(s) com erro?`)) return; const bons = (dados.exames||[]).filter((e:any)=> !(e.nome==='Registro' || !e.nome || !limparDataExame(e.data))); const nd = {...dados, exames: bons}; setDados(nd); salvarNoNavegador(nd); alert(`✅ Apaguei ${ruins.length} com erro.`) }
  function limparTestes() { const testes = (dados.exames||[]).filter((e:any)=> (e.nome||'').toUpperCase().includes('TESTE')); if (testes.length===0) { alert('✅ Nenhum TESTE pra apagar!'); return }; if (!confirm(`Apagar ${testes.length} exame(s) de TESTE?`)) return; const nd={...dados, exames:(dados.exames||[]).filter((e:any)=> !(e.nome||'').toUpperCase().includes('TESTE'))}; setDados(nd); salvarNoNavegador(nd); alert('✅ Testes apagados!') }
  function abrirNovaClinica() { setEditandoClinica(null); setFormClinica({ status:'Ativa', convenio:'Vigente', empresa: usuario?.tipo==='empresa' ? usuario.empresa : '' }); setModalClinica(true) }
