  function salvarClinica() { if (!formClinica.nome) { alert('⚠️ Coloca o nome da clínica!'); return }; const lista = [...(dados.clinicas||[])]; if (editandoClinica) { const idx = lista.findIndex((x:any)=>(x.id||x._id)===(editandoClinica.id||editandoClinica._id)); if (idx>=0) lista[idx]={...lista[idx], ...formClinica} } else { lista.push({...formClinica, id: Date.now().toString()}) }; const nd={...dados, clinicas: lista}; setDados(nd); salvarNoNavegador(nd); setClinicaSelecionada(formClinica.nome); setModalClinica(false); alert(`✅ Clínica ${formClinica.nome} salva!`) }
