  function confirmarAgendamentoFoto() { if (!funcAgendamento) { alert('⚠️ Primeiro escolhe o funcionário!'); return }; if (!diaSelecionado) { alert('⚠️ Clica num dia do calendário!'); return }; if (tiposSelecionados.length===0) { alert('⚠️ Marca pelo menos 1 tipo de exame!'); return }; const novos = tiposSelecionados.map(t => ({ id: Date.now().toString() + Math.random().toString().slice(2,6), nome: funcAgendamento.nome, funcionario: funcAgendamento.nome, tipo: t, data: diaSelecionado, resultado: 'Aguardando', clinica: clinicaSelecionada, empresa: funcAgendamento.empresa || usuario?.empresa || '', status:'Agendado' })); const nd = {...dados, exames: [...(dados.exames||[]), ...novos]}; setDados(nd); salvarNoNavegador(nd); alert(`✅ Agendado!\n\n👷 ${funcAgendamento.nome}\n🏥 ${clinicaSelecionada}\n📅 ${formatarDataExame(diaSelecionado)}\n🩺 ${tiposSelecionados.join(', ')}`); setTiposSelecionados([]); setFuncAgendamento(null); setBuscaFuncAgendamento('') }
  function celularTemDigital() { return typeof window !== 'undefined' && !!window.PublicKeyCredential }
  function bufParaBase64(buf:any) { let s=''; const bytes=new Uint8Array(buf); for(let i=0;i<bytes.length;i++) s+=String.fromCharCode(bytes[i]); return btoa(s) }
  function base64ParaBuf(b64:string) { const s=atob(b64); const bytes=new Uint8Array(s.length); for(let i=0;i<s.length;i++) bytes[i]=s.charCodeAt(i); return bytes.buffer }
  async function confirmarComDigital() { const alvo = funcSelecionado || (dados.funcionarios||[]).find((f:any)=>f.nome===buscaFunc) || (dados.funcionarios||[]).find((f:any)=>f.nome===form.funcionario); if (!alvo) { setDigitalMsg('⚠️ Primeiro escolhe o funcionário!'); return }; if (!celularTemDigital()) { setDigitalMsg('❌ Sem biometria. Usa PIN ou assinatura.'); return }; setDigitalCarregando(true); setDigitalMsg('👆 Encosta o dedo...'); try { const chaveFunc = (alvo.cpf || alvo.nome || '').toString(); const salvas: any = JSON.parse(localStorage.getItem('previx_digital') || '{}'); const idSalvo = salvas[chaveFunc]; const challenge = new Uint8Array(32); window.crypto.getRandomValues(challenge); if (idSalvo) { try { const cred: any = await navigator.credentials.get({ publicKey: { challenge, timeout: 60000, userVerification: 'required', allowCredentials: [{ id: base64ParaBuf(idSalvo), type: 'public-key', transports: ['internal'] }] } } as any); if (cred) { setDigitalOk(true); setDigitalMsg('✅ Digital confirmada!'); setPinErro(''); setDigitalCarregando(false); return } } catch {} }; setDigitalMsg('👆 Primeira vez! Vai aparecer pra criar a chave...'); const userId = new TextEncoder().encode(chaveFunc.slice(0, 32)); const nova: any = await navigator.credentials.create({ publicKey: { challenge, rp: { name: 'PREVIX SST', id: window.location.hostname }, user: { id: userId, name: alvo.nome || 'funcionario', displayName: alvo.nome || 'Funcionario' }, pubKeyCredParams: [{ alg: -7, type: 'public-key' }, { alg: -257, type: 'public-key' }], authenticatorSelection: { authenticatorAttachment: 'platform', userVerification: 'required', requireResidentKey: true }, timeout: 60000, attestation: 'none' } } as any); if (nova) { salvas[chaveFunc] = bufParaBase64(nova.rawId); localStorage.setItem('previx_digital', JSON.stringify(salvas)); setDigitalOk(true); setDigitalMsg('✅ Digital cadastrada e confirmada!') } } catch (err: any) { setDigitalMsg('❌ Não deu pra ler a digital. Usa PIN / assinatura.') }; setDigitalCarregando(false) }
  function iniciarAssinatura(e:any) { const canvas = canvasRef.current; if (!canvas) return; const rect = canvas.getBoundingClientRect(); const x = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left; const y = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top; const ctx = canvas.getContext('2d'); ctx.beginPath(); ctx.moveTo(x,y); ctx.lineWidth = 2.5; ctx.strokeStyle = '#0f172a'; ctx.lineCap = 'round'; setDesenhando(true) }
  function desenharAssinatura(e:any) { if (!desenhando) return; const canvas = canvasRef.current; const rect = canvas.getBoundingClientRect(); const x = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left; const y = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top; const ctx = canvas.getContext('2d'); ctx.lineTo(x,y); ctx.stroke(); setTemAssinatura(true) }
  function terminarAssinatura() { if (!desenhando) return; setDesenhando(false); const canvas = canvasRef.current; if (canvas) setAssinatura(canvas.toDataURL('image/png')) }
  function limparAssinatura() { const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); ctx.clearRect(0,0,canvas.width,canvas.height); setAssinatura(''); setTemAssinatura(false) }
  function gerarTermoPDF(entrega:any) { const func = (dados.funcionarios||[]).find((f:any)=>f.nome===entrega.funcionario) || {}; const empresaNome = entrega.empresa || func.empresa || usuario?.empresa || 'PREVIX SST'; const dataFmt = entrega.data_entrega ? entrega.data_entrega.split('-').reverse().join('/') : new Date().toLocaleDateString('pt-BR'); const assinaturaImg = entrega.assinatura || assinatura || ''; const metodo = entrega.metodo || (entrega.assinatura ? 'Assinatura' : 'PIN'); const html = `<html><head><meta charset="utf-8"><title>Termo - ${entrega.funcionario}</title><style>body{font-family:Arial,sans-serif;padding:40px;color:#0f172a;max-width:800px;margin:0 auto}.topo{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #0d9488;padding-bottom:16px}.logo{font-size:28px;font-weight:900}.logo span{color:#0d9488}.caixa{border:1px solid #cbd5e1;border-radius:12px;padding:16px;margin:12px 0}.linha{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px dashed #e2e8f0}.termo{line-height:1.7;text-align:justify;margin:20px 0}.assinatura{margin-top:40px;text-align:center}.assinatura img{max-width:280px;max-height:100px}.linha-ass{border-top:1px solid #0f172a;width:320px;margin:8px auto 4px}.selo{display:inline-block;background:#dcfce7;color:#15803d;padding:6px 14px;border-radius:20px;font-weight:800}@media print{button{display:none}}</style></head><body><div class="topo"><div><div class="logo">PREVIX <span>SST</span></div></div><div>Nº ${entrega.id?.toString().slice(-6) || '000001'}</div></div><h1 style="text-align:center">Termo de Entrega de EPI</h1><div style="text-align:center"><span class="selo">✅ MÉTODO: ${metodo.toUpperCase()}</span></div><div class="caixa"><div class="linha"><b>Empresa:</b><span>${empresaNome}</span></div><div class="linha"><b>Funcionário:</b><span>${entrega.funcionario || '-'}</span></div><div class="linha"><b>CPF:</b><span>${func.cpf || '-'}</span></div></div><div class="caixa"><div class="linha"><b>EPI:</b><span>${entrega.nome || '-'}</span></div><div class="linha"><b>Data:</b><span>${dataFmt}</span></div></div><p class="termo">Declaro que recebi o EPI acima descrito, em perfeito estado.</p><div class="assinatura">${assinaturaImg ? `<img src="${assinaturaImg}" />` : `<div style="height:60px"></div>`}<div class="linha-ass"></div><div style="font-weight:800">${entrega.funcionario || ''}</div></div><div style="text-align:center;margin-top:20px"><button onclick="window.print()" style="background:#0d9488;color:white;border:none;padding:14px 28px;border-radius:20px;font-weight:800">🖨️ Imprimir / PDF</button></div></body></html>`; const w = window.open('', '_blank'); if (w) { w.document.write(html); w.document.close() } }
  function handleArquivo(e:any) { const file = e.target.files?.[0]; if (!file) return; if (file.size > 4*1024*1024) { alert('⚠️ Máximo 4MB'); return }; setSubindoArquivo(true); setArquivoNome(file.name); const reader = new FileReader(); reader.onload = () => { setForm((prev:any)=>({...prev, arquivoNome: file.name, arquivoData: reader.result, titulo: prev.titulo || file.name.replace('.pdf','') })); setSubindoArquivo(false) }; reader.readAsDataURL(file) }
  function baixarArquivo(item:any) { if (!item.arquivoData) { alert('Sem arquivo.'); return }; const a = document.createElement('a'); a.href = item.arquivoData; a.download = item.arquivoNome || `doc.pdf`; a.click() }
  function verArquivo(item:any) { if (!item.arquivoData) { alert('Sem arquivo.'); return }; const w = window.open(); if (w) { w.document.write(`<iframe src="${item.arquivoData}" style="width:100%;height:100vh;border:none"></iframe>`) } else baixarArquivo(item) }
