    if (aba==='documentos') { formFinal.pasta = pastaSelecionadaForm || 'Outros'; formFinal.tipo = formFinal.pasta; if (!formFinal.titulo) { alert('⚠️ Título!'); return }; if (usuario?.tipo === 'empresa') formFinal.empresa = usuario.empresa }
    if (aba==='empresas') { if (!formFinal.login && formFinal.nome) formFinal.login = formFinal.nome.toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,12); if (!formFinal.senha) formFinal.senha = gerarSenhaForte() }
