                  {aba==='inspecoes' && (<><div style={{fontSize:48}}>📋</div><div style={{fontWeight:900,fontSize:18,marginTop:8}}>Nenhuma inspeção ainda</div><p style={{color:'#64748b',fontSize:14}}>Clica em <b>＋ Nova Inspeção</b>.</p></>)}
                  {aba!=='documentos' && aba!=='inspecoes' && (<><div style={{fontSize:48}}>📭</div><div style={{fontWeight:900,fontSize:18,marginTop:8}}>Nenhum registro aqui ainda</div></>)}
